import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputString = scanner.nextLine();
        StringBuilder outputString = new StringBuilder();
        boolean atFlagged = false;
        inputString += "###";

        for (int idx = 0; idx < inputString.length() - 3; idx++) {
            if (outputString.length() == 0) {
                outputString.append(inputString.charAt(idx));
                continue;
            }
            if (inputString.charAt(idx) == 'd' && inputString.charAt(idx + 1) == 'o' && inputString.charAt(idx + 2) == 't') {
                outputString.append('.');
                idx += 2;
            } else if (inputString.charAt(idx) == 'a' && inputString.charAt(idx + 1) == 't' && !atFlagged) {
                atFlagged = true;
                outputString.append('@');
                idx++;
            } else {
                outputString.append(inputString.charAt(idx));
            }
        }

        if (outputString.length() > 0 && outputString.charAt(outputString.length() - 1) == '.') {
            outputString.setCharAt(outputString.length() - 1, 'd');
            outputString.append("ot");
        }

        System.out.println(outputString.toString());
        scanner.close();
    }
}
